import { get_asset_categories } from "@/mixins/GetAssetCategoryList.js";
import { get_asset_sub_categories } from "@/mixins/GetAssetSubCategories.js";
import { get_location_details } from "@/mixins/GetLocations.js";
import { initiate_asset_request } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    requestDialog: Boolean
  },
  mixins: [get_asset_categories, get_asset_sub_categories, get_location_details],
  data() {
    return {
      categoriesName: "",
      categoriesitems: [],
      allSubCategories: [],
      assetSubCategoriesList: [],
      subcategory: "",
      selectedLocation: "",
      commentField: "",
      loading: false,
      subCheck: false
    };
  },
  watch: {
    requestDialog: {
      async handler() {
        if (this.requestDialog == true) {
          await this.get_asset_categories();
          this.categoriesitems = this.assetCategories;
          // console.log("categoriesitems", this.categoriesitems)
          this.subCheck = true;
          await this.get_asset_sub_categories();
          this.allSubCategories = this.assetSubCategories;
          this.subCheck = false;
          await this.get_location_details();
        }
      },
      immediate: true
    }
  },
  methods: {
    fetch_sub_data() {
      var filteredArray = this.assetSubCategories.filter(obj => obj.category_id === this.categoriesName);
      this.assetSubCategoriesList = [];
      filteredArray.forEach(element => {
        this.assetSubCategoriesList.push({
          text: element.sub_category_name,
          value: element.sub_category_id
        });
      });
      this.subcategory = "";
    },
    async validate_data() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.request_added();
      }
    },
    async request_added() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(initiate_asset_request, {
          input: {
            user_email_id: data.user.user_email_id,
            category_id: this.categoriesName,
            sub_category_id: this.subcategory == "" ? undefined : this.subcategory,
            asset_location_id: this.selectedLocation == "" ? undefined : this.selectedLocation,
            asset_description: this.commentField == "" ? undefined : this.commentField
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.initiate_asset_request);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$refs.form.reset();
          this.commentField = "";
          this.categoriesName = "";
          this.subcategory = "";
          this.selectedLocation = "";

          // this.fetch_audit_message();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    },
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form.reset();
      this.commentField = "";
      this.categoriesName = "";
      this.subcategory = "";
      this.selectedLocation = "";
    }
  }
};
